examples.check:
G = {1: {2, 4}, 2: {1, 3}, 3: {2, 4}, 4: {1, 3}}
H = {1: {3, 4}, 2: {3, 4}, 3: {1, 2}, 4: {1, 2}}
degG = [len(G[v]) for v in sorted(G)]
degH = [len(H[v]) for v in sorted(H)]
for d in sorted(degG):
    print(d)
for d in sorted(degH):
    print(d)
f = {1: 1, 2: 3, 3: 2, 4: 4}
ok = all((v in G[u]) == (f[v] in H[f[u]]) for u in G for v in G if u < v)
ok = ok and len(set(f.values())) == 4
print(1 if ok else 0)

